stylesheets.css:
:root { --ground: #F6F8FA; --panel: #FFFFFF; --ink: #1B232C; --dim: #5F6B77; --line: #E6EBF0; --live: #0E7490; --live-bg: #EDF6F8; --hard: #C62828; --hard-bg: #FBEFEF; --soft: #D97706; --soft-bg: #FBF1E3; --clean: #2E7D32; --clean-bg: #E9F3EA; --shadow: 0 1px 2px rgba(27,35,44,.06),0 2px 8px rgba(27,35,44,.05); --serif: 'Iowan Old Style',Georgia,'Times New Roman',serif; --mono: ui-monospace,'SF Mono',Menlo,Consolas,monospace; --code-bg: #141A20; --code-ink: #D7E0E8; }
* { box-sizing: border-box; margin: 0px; }
body { background: var(--ground); color: var(--ink); font: 15px / 1.62 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; }
code, pre { font-family: var(--mono); }
.topbar { display: flex; gap: 20px; align-items: baseline; flex-wrap: wrap; max-width: 1150px; margin: 0px auto; padding: 22px 32px 8px; font-size: 13px; }
.topbar .brand { font-weight: 700; color: var(--ink); }
.topbar .pid { font-family: var(--mono); font-size: 13px; color: var(--dim); }
.topbar .act { margin-left: auto; font-size: 12.5px; color: var(--live); background: var(--live-bg); border-radius: 99px; padding: 3px 14px; }
.rec { font-family: var(--mono); font-size: 12px; color: var(--dim); }
.rec .dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--hard); margin-right: 5px; vertical-align: 1px; animation: 1.6s ease 0s infinite normal none running pulse; }
@keyframes pulse { 
  50% { opacity: 0.25; }
}
@media (prefers-reduced-motion: reduce) {
  .rec .dot { animation: auto ease 0s 1 normal none running none; }
}
.cols { display: grid; grid-template-columns: minmax(0px, 1fr) 312px; gap: 32px; max-width: 1150px; margin: 0px auto; padding: 14px 32px 64px; align-items: start; }
@media (max-width: 820px) {
  .cols { grid-template-columns: 1fr; }
}
.main-col { min-width: 0px; }
.pane-slot:empty { display: none; }
.pane-slot:not(:empty) { margin-top: 20px; }
.stepcard { background: var(--panel); border-radius: 8px; box-shadow: var(--shadow); padding: 32px 36px; }
.stepcard h1, .stepcard .title, main h2 { font-family: var(--serif); font-weight: 600; font-size: 29px; line-height: 1.22; margin: 0px 0px 14px; text-wrap: balance; }
.eyebrow { font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dim); margin: 0px 0px 12px; }
.eyebrow .act2 { color: var(--hard); font-weight: 600; }
.stepcopy { max-width: 60ch; color: var(--ink); margin: 0px 0px 26px; }
.stepcopy em { color: var(--dim); font-style: normal; }
.stepcopy p { margin: 0px 0px 14px; }
.stepcopy p:last-child { margin-bottom: 0px; }
.stepcard p, .entrybox p, .task p { margin: 0px 0px 12px; }
.stepcard p:last-child, .entrybox p:last-child, .task p:last-child { margin-bottom: 0px; }
.stepcard ul, .stepcard ol, .entrybox ul, .entrybox ol { margin: 0px 0px 12px; padding-left: 20px; }
.task { background: var(--ground); border-radius: 6px; padding: 22px 24px; margin: 0px 0px 18px; }
.task .label { font-family: var(--mono); font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dim); margin: 0px 0px 14px; }
.question { font-size: 17px; font-weight: 600; margin: 0px 0px 16px; }
.answerchip { display: flex; align-items: center; gap: 10px; background: var(--panel); border-radius: 6px; box-shadow: inset 0 0 0 1px var(--line); padding: 10px 14px; margin: 0px 0px 16px; max-width: 340px; }
.answerchip code { font-family: var(--mono); font-size: 14px; }
.answerchip .hint { margin-left: auto; }
textarea, input[type="text"] { width: 100%; font: inherit; padding: 10px 12px; border: 1px solid var(--line); border-radius: 6px; background: var(--panel); color: var(--ink); resize: vertical; }
textarea { min-height: 74px; }
input[type="text"] { max-width: 440px; }
textarea:focus, input[type="text"]:focus { outline: 2px solid var(--live); outline-offset: -1px; }
.autotype-field.busy { background: var(--panel); color: var(--dim); cursor: not-allowed; }
.hint { font-size: 12px; color: var(--dim); }
.rule { padding: 14px 16px; border-left: 3px solid var(--soft); background: var(--soft-bg); border-radius: 0px 6px 6px 0px; margin: 0px 0px 14px; font-size: 15px; }
.rule.fallback-note { border-left-color: var(--soft); }
.btnrow { display: flex; gap: 14px; align-items: center; margin-top: 20px; flex-wrap: wrap; }
.btn { font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-weight: 600; padding: 10px 22px; border-radius: 6px; border: none; background: var(--ink); color: rgb(255, 255, 255); cursor: pointer; }
.btn:hover { background: rgb(44, 57, 71); }
.btn:focus-visible, button:focus-visible, a:focus-visible { outline: 2px solid var(--live); outline-offset: 2px; }
.secondary { margin-top: 14px; font-size: 13.5px; }
.secondary a { color: var(--dim); text-decoration: underline; text-underline-offset: 3px; }
.skip { color: var(--dim); text-decoration: underline; text-underline-offset: 3px; }
.skip:hover { color: var(--ink); }
.entrybox { background: var(--ground); border-radius: 6px; padding: 22px 24px; margin: 0px 0px 18px; }
.endguard { display: inline-block; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-weight: 600; padding: 10px 22px; border-radius: 6px; border: none; background: var(--ink); color: rgb(255, 255, 255); cursor: pointer; margin-top: 14px; }
.endguard:hover { background: rgb(44, 57, 71); }
.endguard:focus-visible { outline: 2px solid var(--live); outline-offset: 2px; }
.endguard.floating { position: fixed; right: 24px; bottom: 24px; z-index: 2147483647; margin: 0px; border: 1px solid rgba(255, 255, 255, 0.35); box-shadow: rgba(0, 0, 0, 0.45) 0px 6px 24px; }
pre { background: var(--code-bg); color: var(--code-ink); padding: 14px 16px; border-radius: 6px; overflow-x: auto; font: 12.5px/1.5 var(--mono); margin: 0px 0px 18px; }
pre code { background: none; padding: 0px; }
.code-tabs { display: flex; gap: 6px; margin: 2px 0px 10px; }
.code-tab { font: 12px var(--mono); padding: 4px 12px; border: none; border-radius: 99px; background: var(--ground); color: var(--dim); cursor: pointer; }
.code-tab.active { background: var(--live-bg); color: var(--live); font-weight: 700; }
.violations { display: flex; gap: 8px; flex-wrap: wrap; margin: 0px 0px 14px; }
.chip { font-size: 12px; padding: 4px 10px; border-radius: 99px; box-shadow: inset 0 0 0 1px var(--line); color: var(--dim); }
.chip.hot { background: var(--hard-bg); color: var(--hard); box-shadow: none; }
.scramble { position: relative; user-select: none; }
.scramble .content { filter: blur(6px); opacity: 0.7; }
.scramble .banner { position: absolute; inset: 0px; display: flex; align-items: center; justify-content: center; }
.scramble .banner span { background: var(--hard); color: rgb(255, 255, 255); font: 700 12px/1 var(--mono); letter-spacing: 0.12em; padding: 8px 14px; border-radius: 6px; }
.instrument { display: flex; flex-direction: column; gap: 16px; position: sticky; top: 22px; }
.card { background: var(--panel); border-radius: 8px; box-shadow: var(--shadow); padding: 18px 20px; }
.card h3, .lp-title { font-size: 11.5px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dim); font-weight: 600; margin: 0px 0px 4px; }
.card .sub { font-size: 12px; color: var(--dim); line-height: 1.5; margin: 0px 0px 10px; }
.check { list-style: none; margin: 0px; padding: 0px; font-size: 12.5px; max-height: calc(-220px + 100vh); overflow-y: auto; }
.check li { display: flex; align-items: center; gap: 9px; padding: 4.5px 0px; color: var(--dim); }
.check li.lit { color: var(--ink); }
.check li.lit .lamp { background: var(--clean); border-color: var(--clean); }
.check li.lit.hardlit .lamp { background: var(--hard); border-color: var(--hard); }
.check li.always .lamp { background: var(--line); border-color: var(--line); }
.check li .n { margin-left: auto; font-family: var(--mono); font-size: 11.5px; }
.check .hint, .check li.grouphead { padding-top: 12px; font-size: 10.5px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dim); }
.check.awaiting li:not(.hint):not(.grouphead) { opacity: 0.55; }
.lamp { flex: 0 0 auto; width: 8px; height: 8px; border-radius: 50%; border: 1.5px solid var(--line); background: transparent; }
body[data-view="act2"] .check li.guardrow { color: var(--hard); }
body[data-view="act2"] .check li.guardrow .lamp { background: var(--hard); border-color: var(--hard); }
@keyframes lamp-pulse { 
  0% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.8); opacity: 0.4; }
  100% { transform: scale(1); opacity: 1; }
}
.lamp.lamp-pulse { animation: 0.6s ease-out 0s 1 normal none running lamp-pulse; }
@media (prefers-reduced-motion: reduce) {
  .lamp.lamp-pulse { animation: auto ease 0s 1 normal none running none; }
}
.lp-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 0px 0px 10px; }
.lp-tabs { display: flex; gap: 6px; }
.lp-tab { font: 12px var(--mono); padding: 4px 12px; border: none; border-radius: 99px; background: var(--ground); color: var(--dim); cursor: pointer; }
.lp-tab.active { background: var(--live-bg); color: var(--live); font-weight: 700; }
.lp-body { display: grid; grid-template-columns: 80px minmax(0px, 1fr); gap: 8px; }
.lp-trials { display: flex; flex-direction: column; gap: 4px; min-width: 0px; flex: 0 0 auto; border-right: 1px solid var(--line); padding-right: 8px; max-height: 290px; overflow-y: auto; }
.lp-trial-tab { font-family: inherit; font-size: 11px; line-height: 1.35; text-align: left; padding: 4px 6px; border: none; border-radius: 5px; background: var(--ground); color: var(--dim); cursor: pointer; flex: 0 0 auto; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden; max-height: calc(4.05em + 8px); }
.lp-trial-tab[aria-pressed="true"] { background: var(--live-bg); color: var(--live); font-weight: 700; }
.lp-views { min-width: 0px; }
.lp-stream { font-family: var(--mono); font-size: 11px; line-height: 1.5; max-height: 290px; overflow-y: auto; }
[data-role="live-pane"].promoted { width: 100%; }
[data-role="live-pane"].promoted .lp-stream { max-height: 560px; }
.lp-cols, .lp-row { display: grid; gap: 6px; grid-template-columns: 37px minmax(0px, 0.7fr) minmax(0px, 1.15fr) minmax(0px, 1.5fr); padding: 4px 0px; border-top: 1px solid var(--line); }
.lp-trial, .lp-event { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lp-detail { overflow-wrap: anywhere; }
.lp-cols { color: var(--dim); font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; border-top: none; }
.lp-t { color: var(--dim); font-variant-numeric: tabular-nums; white-space: nowrap; }
.lp-trial { color: var(--dim); }
.lp-event { font-weight: 600; }
.lp-detail { color: var(--dim); }
.lp-row.hard .lp-event { color: var(--hard); font-weight: 700; }
.lp-row.lp-off { display: none; }
.lp-body[data-view="json"] { grid-template-columns: minmax(0px, 1fr); }
.lp-body[data-view="json"] .lp-trials { display: none; }
[data-role="live-pane"].promoted .lp-body { grid-template-columns: 156px minmax(0px, 1fr); }
.results-mode [data-role="live-pane"] .lp-body { grid-template-columns: 172px minmax(0px, 1fr); }
[data-role="live-pane"].promoted .lp-trials { max-height: 560px; }
[data-role="live-pane"].promoted .lp-trial-tab, .results-mode [data-role="live-pane"] .lp-trial-tab { display: block; font-size: 12px; -webkit-line-clamp: none; max-height: none; }
[data-role="live-pane"].promoted .lp-stream, .results-mode [data-role="live-pane"] .lp-stream { font-size: 11.8px; }
[data-role="live-pane"].promoted .lp-cols, [data-role="live-pane"].promoted .lp-row, .results-mode [data-role="live-pane"] .lp-cols, .results-mode [data-role="live-pane"] .lp-row { grid-template-columns: 44px minmax(90px, 0.8fr) minmax(140px, 1.19fr) minmax(0px, 2fr); gap: 8px; }
[data-role="live-pane"].promoted .lp-trial, [data-role="live-pane"].promoted .lp-event, .results-mode [data-role="live-pane"] .lp-trial, .results-mode [data-role="live-pane"] .lp-event { white-space: normal; text-overflow: clip; overflow-wrap: break-word; overflow: hidden; }
.lp-json { background: none; color: var(--ink); margin: 0px; padding: 0px; border-radius: 0px; max-height: 290px; overflow: auto; font: 11.8px/1.6 var(--mono); }
.lp-caption { margin: 10px 0px 0px; font-size: 11.5px; color: var(--dim); line-height: 1.5; }
.lp-caption code { font-family: var(--mono); font-size: 11px; }
.files { display: flex; gap: 10px; flex-wrap: wrap; margin: 0px 0px 14px; }
.file { display: flex; flex-direction: column; gap: 10px; min-width: 190px; background: var(--panel); box-shadow: var(--shadow); border-radius: 6px; padding: 10px 14px; font: 13px/1.4 var(--mono); }
.file-info { display: flex; flex-direction: column; gap: 2px; }
.file small { display: block; color: var(--dim); font-size: 11px; }
.file .file-desc { display: block; color: var(--dim); font-size: 11px; }
.file .file-actions { display: flex; gap: 12px; align-items: center; }
.file .file-actions a { color: var(--live); font-size: 12px; }
.file .file-caveat { color: var(--dim); font-size: 11px; font-style: italic; max-width: 220px; margin: 0px; }
.filetext-dialog { max-width: 640px; width: 90vw; padding: 18px; border: none; border-radius: 8px; box-shadow: var(--shadow); background: var(--panel); color: var(--ink); }
.filetext-dialog::backdrop { background: rgba(27, 35, 44, 0.4); }
.filetext-dialog h3 { margin: 0px 0px 10px; font: 600 13px/1 var(--mono); }
.filetext-dialog pre { max-height: 60vh; overflow: auto; user-select: text; margin: 0px 0px 14px; }
.weight-editors { display: flex; gap: 14px; flex-wrap: wrap; margin: 0px 0px 10px; }
.weight-editors label { font-size: 13px; display: flex; align-items: center; gap: 6px; }
.weight-editors input[type="number"] { width: 56px; }
.replicate h3 { font-size: 15px; font-weight: 600; margin: 18px 0px 8px; }
.replicate h3:first-child { margin-top: 0px; }
.results-mode .main-col { grid-column: 1 / -1; }
.results-mode .instrument { grid-column: 1 / -1; }
.yourreport { border-left: 3px solid var(--live); padding: 2px 0px 2px 16px; margin: 0px 0px 18px; }
.yourreport h3 { font-size: 20px; margin: 0px 0px 8px; }
.yourreport li { margin: 0px 0px 8px; max-width: 60ch; }
.yourreport .t-hard { color: var(--hard); font-weight: 700; }
.yourreport .t-soft { color: var(--soft); font-weight: 700; }
.yourreport .t-clean { color: var(--clean); font-weight: 700; }
.results-frame { width: 100%; min-height: 900px; border: 0px; border-radius: 8px; box-shadow: var(--shadow); background: var(--panel); }
.replay-host-card { background: var(--panel); border-radius: 8px; box-shadow: var(--shadow); padding: 20px 24px; margin: 18px 0px 0px; }
.replay-host-card h3 { font-size: 15px; font-weight: 600; margin: 0px 0px 6px; }
.replay-host-card .hint { margin: 0px 0px 14px; }
.replay-host-frame { width: 100%; min-height: 520px; border: 0px; border-radius: 6px; }

